    public int? PerformanceInsightsRetentionPeriod { get; set; }

    /// <summary>
    /// The log types to be enabled for export to CloudWatch Logs for a specific DB instance. A change to the CloudwatchLogsExportConfiguration parameter is always applied to the DB instance immediately. Therefore, the ApplyImmediately parameter has no effect. This setting doesn't apply to RDS Custom DB instances. The following values are valid for each DB engine: • Aurora MySQL - audit | error | general | slowquery | iam-db-auth-error • Aurora PostgreSQL - postgresql | iam-db-auth-error • RDS for MySQL - error | general | slowquery | iam-db-auth-error • RDS for PostgreSQL - postgresql | upgrade | iam-db-auth-error For more information about exporting CloudWatch Logs for Amazon RDS, see Publishing Database Logs to Amazon CloudWatch Logs in the Amazon RDS User Guide . For more information about exporting CloudWatch Logs for Amazon Aurora, see Publishing Database Logs to Amazon CloudWatch Logs in the Amazon Aurora User Guide . EnableLogTypes -&gt; (list) The list of log types to enable. The following values are valid for each DB engine: • Aurora MySQL - audit | error | general | slowquery • Aurora PostgreSQL - postgresql • RDS for MySQL - error | general | slowquery • RDS for PostgreSQL - postgresql | upgrade (string) DisableLogTypes -&gt; (list) The list of log types to disable. The following values are valid for each DB engine: • Aurora MySQL - audit | error | general | slowquery • Aurora PostgreSQL - postgresql • RDS for MySQL - error | general | slowquery • RDS for PostgreSQL - postgresql | upgrade (string) Shorthand Syntax: EnableLogTypes=string,string,DisableLogTypes=string,string JSON Syntax: { "EnableLogTypes": ["string", ...], "DisableLogTypes": ["string", ...] }
    /// </summary>
    [CliOption("--cloudwatch-logs-export-configuration")]
    public string? CloudwatchLogsExportConfiguration { get; set; }

    /// <summary>
    /// The number of CPU cores and the number of threads per core for the DB instance class of the DB instance. This setting doesn't apply to RDS Custom DB instances. (structure) Contains the processor features of a DB instance class. To specify the number of CPU cores, use the coreCount feature name for the Name parameter. To specify the number of threads per core, use the threadsPerCore feature name for the Name parameter. You can set the processor features of the DB instance class for a DB instance when you call one of the following actions: • CreateDBInstance • ModifyDBInstance • RestoreDBInstanceFromDBSnapshot • RestoreDBInstanceFromS3 • RestoreDBInstanceToPointInTime You can view the valid processor values for a particular instance class by calling the DescribeOrderableDBInstanceOptions action and specifying the instance class for the DBInstanceClass parameter. In addition, you can use the following actions for DB instance class processor information: • DescribeDBInstances • DescribeDBSnapshots • DescribeValidDBInstanceModifications If you call DescribeDBInstances , ProcessorFeature returns non-null values only if the following conditions are met: • You are accessing an Oracle or SQL Server DB instance. • Your Oracle or SQL Server DB instance class supports configuring the number of CPU cores and threads per core. • The current number CPU cores and threads is set to a non-default value. For more information, see Configuring the processor for a DB instance class in RDS for Oracle , Optimizing your RDS for SQL Server CPU , and DB instance classes in the Amazon RDS User Guide. Name -&gt; (string) The name of the processor feature. Valid names are coreCount and threadsPerCore . Value -&gt; (string) The value of a processor feature. Shorthand Syntax: Name=string,Value=string ... JSON Syntax: [ { "Name": "string", "Value": "string" } ... ]
    /// </summary>
    [CliOption("--processor-features", GroupValues = true)]
    public IEnumerable<string>? ProcessorFeatures { get; set; }

    /// <summary>
    /// Specifies whether the DB instance class of the DB instance uses its default processor features. This setting doesn't apply to RDS Custom DB instances.
    /// </summary>
    [CliFlag("--use-default-processor-features", NegatedName = "--no-use-default-processor-features")]
    public bool? UseDefaultProcessorFeatures { get; set; }

    /// <summary>
    /// Specifies whether the DB instance has deletion protection enabled. The database can't be deleted when deletion protection is enabled. By default, deletion protection isn't enabled. For more information, see Deleting a DB Instance . This setting doesn't apply to Amazon Aurora DB instances. You can enable or disable deletion protection for the DB cluster. For more information, see ModifyDBCluster . DB instances in a DB cluster can be deleted even when deletion protection is enabled for the DB cluster.
    /// </summary>
    [CliFlag("--deletion-protection", NegatedName = "--no-deletion-protection")]
    public bool? DeletionProtection { get; set; }

    /// <summary>
    /// The upper limit in gibibytes (GiB) to which Amazon RDS can automatically scale the storage of the DB instance. For more information about this setting, including limitations that apply to it, see Managing capacity automatically with Amazon RDS storage autoscaling in the Amazon RDS User Guide . This setting doesn't apply to RDS Custom DB instances.
    /// </summary>
    [CliOption("--max-allocated-storage")]
    public int? MaxAllocatedStorage { get; set; }

    /// <summary>
    /// Specifies whether the DB instance is restarted when you rotate your SSL/TLS certificate. By default, the DB instance is restarted when you rotate your SSL/TLS certificate. The certificate is not updated until the DB instance is restarted. WARNING: Set this parameter only if you are not using SSL/TLS to connect to the DB instance. If you are using SSL/TLS to connect to the DB instance, follow the appropriate instructions for your DB engine to rotate your SSL/TLS certificate: • For more information about rotating your SSL/TLS certificate for RDS DB engines, see Rotating Your SSL/TLS Certificate. in the Amazon RDS User Guide. • For more information about rotating your SSL/TLS certificate for Aurora DB engines, see Rotating Your SSL/TLS Certificate in the Amazon Aurora User Guide . This setting doesn't apply to RDS Custom DB instances.
    /// </summary>
    [CliFlag("--certificate-rotation-restart", NegatedName = "--no-certificate-rotation-restart")]
    public bool? CertificateRotationRestart { get; set; }

    /// <summary>
    /// The open mode of a replica database. This parameter is only supported for Db2 DB instances and Oracle DB instances. Db2 Standby DB replicas are included in Db2 Advanced Edition (AE), Db2 Community Edition (CE), and Db2 Standard Edition (SE). The main use case for standby replicas is cross-Region disaster recovery. Because it doesn't accept user connections, a standby replica can't serve a read-only workload. You can create a combination of standby and read-only DB replicas for the same primary DB instance. For more information, see Working with replicas for Amazon RDS for Db2 in the Amazon RDS User Guide . To create standby DB replicas for RDS for Db2, set this parameter to mounted . Oracle Mounted DB replicas are included in Oracle Database Enterprise Edition. The main use case for mounted replicas is cross-Region disaster recovery. The primary database doesn't use Active Data Guard to transmit information to the mounted replica. Because it doesn't accept user connections, a mounted replica can't serve a read-only workload. You can create a combination of mounted and read-only DB replicas for the same primary DB instance. For more information, see Working with read replicas for Amazon RDS for Oracle in the Amazon RDS User Guide . For RDS Custom, you must specify this parameter and set it to mounted . The value won't be set by default. After replica creation, you can manage the open mode manually. Possible values: • open-read-only • mounted
    /// </summary>
    [CliOption("--replica-mode")]
    public AwsRdsModifyDbInstanceReplicaMode? ReplicaMode { get; set; }

    /// <summary>
    /// The automation mode of the RDS Custom DB instance. If full , the DB instance automates monitoring and instance recovery. If all paused , the instance pauses automation for the duration set by ResumeFullAutomationModeMinutes . Possible values: • full • all-paused
    /// </summary>
    [CliOption("--automation-mode")]
    public AwsRdsModifyDbInstanceAutomationMode? AutomationMode { get; set; }

    /// <summary>
    /// The number of minutes to pause the automation. When the time period ends, RDS Custom resumes full automation. Default: 60 Constraints: • Must be at least 60. • Must be no more than 1,440.
    /// </summary>
    [CliOption("--resume-full-automation-mode-minutes")]
    public int? ResumeFullAutomationModeMinutes { get; set; }

    /// <summary>
    /// Specifies whether to enable a customer-owned IP address (CoIP) for an RDS on Outposts DB instance. A CoIP provides local or external connectivity to resources in your Outpost subnets through your on-premises network. For some use cases, a CoIP can provide lower latency for connections to the DB instance from outside of its virtual private cloud (VPC) on your local network. For more information about RDS on Outposts, see Working with Amazon RDS on Amazon Web Services Outposts in the Amazon RDS User Guide . For more information about CoIPs, see Customer-owned IP addresses in the Amazon Web Services Outposts User Guide .
    /// </summary>
    [CliFlag("--enable-customer-owned-ip", NegatedName = "--no-enable-customer-owned-ip")]
    public bool? EnableCustomerOwnedIp { get; set; }

    /// <summary>
    /// The network type of the DB instance. The network type is determined by the DBSubnetGroup specified for the DB instance. A DBSubnetGroup can support only the IPv4 protocol or the IPv4 and the IPv6 protocols (DUAL ). For more information, see Working with a DB instance in a VPC in the Amazon RDS User Guide. Valid Values: IPV4 | DUAL
    /// </summary>
    [CliOption("--network-type")]
    public string? NetworkType { get; set; }

    /// <summary>
    /// The Amazon Resource Name (ARN) of the recovery point in Amazon Web Services Backup. This setting doesn't apply to RDS Custom DB instances. Constraints: • min: 43 • max: 350 • pattern: arn:aws[a-z-]*:backup:[-a-z0-9]+:[0-9]{12}:[-a-z]+:([a-z0-9\-]+:)?[a-z][a-z0-9\-]{0,255}
    /// </summary>
    [CliOption("--aws-backup-recovery-point-arn")]
    public string? AwsBackupRecoveryPointArn { get; set; }

    /// <summary>
    /// Specifies whether to manage the master user password with Amazon Web Services Secrets Manager. If the DB instance doesn't manage the master user password with Amazon Web Services Secrets Manager, you can turn on this management. In this case, you can't specify MasterUserPassword . If the DB instance already manages the master user password with Amazon Web Services Secrets Manager, and you specify that the master user password is not managed with Amazon Web Services Secrets Manager, then you must specify MasterUserPassword . In this case, Amazon RDS deletes the secret and uses the new password for the master user specified by MasterUserPassword . For more information, see Password management with Amazon Web Services Secrets Manager in the Amazon RDS User Guide. Constraints: • Can't manage the master user password with Amazon Web Services Secrets Manager if MasterUserPassword is specified. • Can't specify for RDS for Oracle CDB instances in the multi-tenant configuration. Use ModifyTenantDatabase instead. • Can't specify the parameters ManageMasterUserPassword and MultiTenant in the same operation.
    /// </summary>
    [CliFlag("--manage-master-user-password", NegatedName = "--no-manage-master-user-password")]
    public bool? ManageMasterUserPassword { get; set; }

    /// <summary>
    /// Specifies whether to rotate the secret managed by Amazon Web Services Secrets Manager for the master user password. This setting is valid only if the master user password is managed by RDS in Amazon Web Services Secrets Manager for the DB instance. The secret value contains the updated password. For more information, see Password management with Amazon Web Services Secrets Manager in the Amazon RDS User Guide. Constraints: • You must apply the change immediately when rotating the master user password.
    /// </summary>
    [CliFlag("--rotate-master-user-password", NegatedName = "--no-rotate-master-user-password")]
    public bool? RotateMasterUserPassword { get; set; }

    /// <summary>
    /// The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and managed in Amazon Web Services Secrets Manager. This setting is valid only if both of the following conditions are met: • The DB instance doesn't manage the master user password in Amazon Web Services Secrets Manager. If the DB instance already manages the master user password in Amazon Web Services Secrets Manager, you can't change the KMS key used to encrypt the secret. • You are turning on ManageMasterUserPassword to manage the master user password in Amazon Web Services Secrets Manager. If you are turning on ManageMasterUserPassword and don't specify MasterUserSecretKmsKeyId , then the aws/secretsmanager KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't use the aws/secretsmanager KMS key to encrypt the secret, and you must use a customer managed KMS key. The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key. To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN. There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.
    /// </summary>
    [CliOption("--master-user-secret-kms-key-id")]
    public string? MasterUserSecretKmsKeyId { get; set; }

    /// <summary>
    /// Specifies whether the to convert your DB instance from the single-tenant conguration to the multi-tenant conguration. This parameter is supported only for RDS for Oracle CDB instances. During the conversion, RDS creates an initial tenant database and associates the DB name, master user name, character set, and national character set metadata with this database. The tags associated with the instance also propagate to the initial tenant database. You can add more tenant databases to your DB instance by using the CreateTenantDatabase operation. WARNING: The conversion to the multi-tenant configuration is permanent and irreversible, so you can't later convert back to the single-tenant configuration. When you specify this parameter, you must also specify ApplyImmediately .
    /// </summary>
    [CliFlag("--multi-tenant", NegatedName = "--no-multi-tenant")]
    public bool? MultiTenant { get; set; }

    /// <summary>
    /// Indicates whether the DB instance has a dedicated log volume (DLV) enabled.
    /// </summary>
    [CliFlag("--dedicated-log-volume", NegatedName = "--no-dedicated-log-volume")]
    public bool? DedicatedLogVolume { get; set; }

    /// <summary>
    /// The target Oracle DB engine when you convert a non-CDB to a CDB. This intermediate step is necessary to upgrade an Oracle Database 19c non-CDB to an Oracle Database 21c CDB. Note the following requirements: • Make sure that you specify oracle-ee-cdb or oracle-se2-cdb . • Make sure that your DB engine runs Oracle Database 19c with an April 2021 or later RU. Note the following limitations: • You can't convert a CDB to a non-CDB. • You can't convert a replica database. • You can't convert a non-CDB to a CDB and upgrade the engine version in the same command. • You can't convert the existing custom parameter or option group when it has options or parameters that are permanent or persistent. In this situation, the DB instance reverts to the default option and parameter group. To avoid reverting to the default, specify a new parameter group with --db-parameter-group-name and a new option group with --option-group-name .
    /// </summary>
    [CliOption("--engine")]
    public string? Engine { get; set; }

    /// <summary>
    /// A list of additional storage volumes to modify or delete for the DB instance. You can create up to 3 additional storage volumes. Additional storage volumes are supported for RDS for Oracle and RDS for SQL Server DB instances only. (structure) Contains details about the modification of an additional storage volume. VolumeName -&gt; (string) [required] The name of the additional storage volume that you want to modify. Valid Values: RDSDBDATA2 | RDSDBDATA3 | RDSDBDATA4 AllocatedStorage -&gt; (integer) The amount of storage allocated for the additional storage volume, in gibibytes (GiB). The minimum is 20 GiB. The maximum is 65,536 GiB (64 TiB). IOPS -&gt; (integer) The number of I/O operations per second (IOPS) provisioned for the additional storage volume. This setting is only supported for Provisioned IOPS SSD (io1 and io2 ) storage types. MaxAllocatedStorage -&gt; (integer) The upper limit in gibibytes (GiB) to which RDS can automatically scale the storage of the additional storage volume. You must provide a value greater than or equal to AllocatedStorage . StorageThroughput -&gt; (integer) The storage throughput value for the additional storage volume, in mebibytes per second (MiBps). This setting applies only to the General Purpose SSD (gp3 ) storage type. StorageType -&gt; (string) The new storage type for the additional storage volume. Valid Values: GP3 | IO2 SetForDelete -&gt; (boolean) Indicates whether to delete the additional storage volume. The value true schedules the volume for deletion. You can delete an additional storage volume only when it doesn't contain database files or other data. Shorthand Syntax: VolumeName=string,AllocatedStorage=integer,IOPS=integer,MaxAllocatedStorage=integer,StorageThroughput=integer,StorageType=string,SetForDelete=boolean ... JSON Syntax: [ { "VolumeName": "string", "AllocatedStorage": integer, "IOPS": integer, "MaxAllocatedStorage": integer, "StorageThroughput": integer, "StorageType": "string", "SetForDelete": true|false } ... ]
    /// </summary>
    [CliOption("--additional-storage-volumes", GroupValues = true)]
    public IEnumerable<string>? AdditionalStorageVolumes { get; set; }

    /// <summary>
    /// Tags to assign to resources associated with the DB instance. Valid Values: • auto-backup - The DB instance's automated backup. (structure) The tags to apply to resources when creating or modifying a DB instance or DB cluster. When you specify a tag, you must specify the resource type to tag, otherwise the request will fail. ResourceType -&gt; (string) The type of resource to tag on creation. Valid Values: • auto-backup - The DB instance's automated backup. • cluster-auto-backup - The DB cluster's automated backup. Tags -&gt; (list) A list of tags. For more information, see Tagging Amazon RDS resources in the Amazon RDS User Guide or Tagging Amazon Aurora and Amazon RDS resources in the Amazon Aurora User Guide . (structure) Metadata assigned to an Amazon RDS resource consisting of a key-value pair. For more information, see Tagging Amazon RDS resources in the Amazon RDS User Guide or Tagging Amazon Aurora and Amazon RDS resources in the Amazon Aurora User Guide . Key -&gt; (string) A key is the required name of the tag. The string value can be from 1 to 128 Unicode characters in length and can't be prefixed with aws: or rds: . The string can only contain only the set of Unicode letters, digits, white-space, '_', '.', ':', '/', '=', '+', '-', '@' (Java regex: "^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$"). Value -&gt; (string) A value is the optional value of the tag. The string value can be from 1 to 256 Unicode characters in length and can't be prefixed with aws: or rds: . The string can only contain only the set of Unicode letters, digits, white-space, '_', '.', ':', '/', '=', '+', '-', '@' (Java regex: "^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$"). Shorthand Syntax: ResourceType=string,Tags=[{Key=string,Value=string},{Key=string,Value=string}] ... JSON Syntax: [ { "ResourceType": "string", "Tags": [ { "Key": "string", "Value": "string" } ... ] } ... ]
    /// </summary>
    [CliOption("--tag-specifications", GroupValues = true)]
    public IEnumerable<string>? TagSpecifications { get; set; }

    /// <summary>
    /// Specifies the authentication type for the master user. With IAM master user authentication, you can change the master DB user to use IAM database authentication. You can specify one of the following values: • password - Use standard database authentication with a password. • iam-db-auth - Use IAM database authentication for the master user. This option is only valid for RDS for PostgreSQL and Aurora PostgreSQL engines. Possible values: • password • iam-db-auth
    /// </summary>
    [CliOption("--master-user-authentication-type")]
    public AwsRdsModifyDbInstanceMasterUserAuthenticationType? MasterUserAuthenticationType { get; set; }

    /// <summary>
    /// The lifecycle type for this DB instance. This setting applies only to RDS for MySQL and RDS for PostgreSQL. For Amazon Aurora DB instances, the engine lifecycle support is managed by the DB cluster. You can use this setting to enroll your DB instance into Amazon RDS Extended Support or to opt out. With RDS Extended Support, you can run the selected major engine version on your DB instance past the end of standard support for that engine version. For more information, see Amazon RDS Extended Support with Amazon RDS in the Amazon RDS User Guide . Valid Values: open-source-rds-extended-support | open-source-rds-extended-support-disabled This setting doesn't apply to RDS Custom DB instances.
    /// </summary>
    [CliOption("--engine-lifecycle-support")]
    public string? EngineLifecycleSupport { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

}
